       "pdf_solucio": "u13/probabilitat-total-bayes/q001/out/tries/bayes-tasca/control-qualitat/solucio.pdf",
       "pdf_curt": "u13/probabilitat-total-bayes/q001/out/tries/bayes-tasca/control-qualitat/enunciat-curt.pdf",
